{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/support-channels.json
    Ways to get help as cards or rows, each with an icon, a title, a sentence and an open link. Axes: layout (grid, list), columns, action (link, none), tone (default, muted).
    Props (p): id, title, channels, open, layout, cols, action, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_channels = ($p['channels'] ?? null)}
{var $v_open = ($p['open'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_action = ($p['action'] ?? 'link')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {capture $c_7}
    {foreach ui_l($v_channels) as $v_c}
      {capture $c_6}
        {capture $c_5}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_c, ['icon'])), 'Size' => 24]])|noescape}
          {capture $c_3}
            {capture $c_1}
              {=ui_text(ui_get($v_c, ['title']))}
            {/capture}
            {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'base', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
            {capture $c_2}
              {=ui_text(ui_get($v_c, ['text']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => 'flex-1'], 'children' => $c_3])|noescape}
          {if ui_t(ui_eq($v_action, 'link'))}
            {capture $c_4}
              {=ui_text($v_open)}
            {/capture}
            {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/', 'Variant' => 'default', 'Attrs' => ui_attrs(['data-testid', 'open'])], 'children' => $c_4])|noescape}
          {/if}
        {/capture}
        {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex flex-1 gap-4', (ui_t(ui_eq($v_layout, 'list')) ? 'items-center' : 'flex-col')]))], 'children' => $c_5])|noescape}
      {/capture}
      {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'default', 'Class' => ui_s(ui_cnv(['h-full', (ui_t(ui_eq($v_layout, 'list')) ? 'flex-row items-center' : '')])), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_6])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_layout, 'list')) ? '1' : $v_cols)), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_7])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_8])|noescape}
